  // recipient currently being processed.
  let stopped = false;
  window.stopBulkDM = () => {
    stopped = true;
    log.warning('Stop requested. Finishing the current DM, then exiting.');
  };

  console.log(`
╔══════════════════════════════════════════════════════════╗
║  💬 BULK DM - XActions                                   ║
║  👤 Author: nichxbt                                      ║
║  🌐 https://xactions.app                                 ║
╚══════════════════════════════════════════════════════════╝
  `);
