  register("detectUnfollowers", function(){
(() => {
  const CONFIG = {
    scrollDelay: 1500,               // ms between scrolls
    maxRetries: 5,                   // Scrolls with no new followers before stopping
    maxScrolls: 0,                   // Maximum scroll attempts (0 = no limit)
    maxFollowers: 0,                 // Stop scanning after this many followers (0 = no limit)
    autoDownload: true,              // Download a file when the comparison finds changes
    downloadFormat: 'txt',           // 'txt' = unfollower usernames, 'report' = full text report
                                     // (unfollowers and new followers), 'json' = JSON file
    showDisplayNames: false,         // Print display names next to usernames in the results
    storageKey: 'xactions_my_followers',
    legacyStorageKeys: ['xactions_followers'], // Older snapshot keys read when storageKey has none
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  const STORAGE_KEY = CONFIG.storageKey;
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  // Check we're on the right page
  const isFollowersPage = window.location.pathname.includes('/followers');
  if (!isFollowersPage) {
    console.error('❌ Please navigate to your FOLLOWERS page first!');
    console.log('👉 Go to: https://x.com/YOUR_USERNAME/followers');
    return;
  }

  const getCurrentUsername = () => {
    const match = window.location.pathname.match(/^\/([^/]+)\/followers/);
    return match ? match[1] : 'unknown';
  };

  // username -> display name, filled while scanning
  const displayNames = {};

  const scrapeFollowers = async () => {
    const followers = new Set();
    let previousSize = 0;
    let retries = 0;
    let scrolls = 0;
    const maxRetries = CONFIG.maxRetries;

    console.log('🔍 Scanning your followers...');

    while (retries < maxRetries) {
      if (CONFIG.maxScrolls > 0 && scrolls >= CONFIG.maxScrolls) break;
      if (CONFIG.maxFollowers > 0 && followers.size >= CONFIG.maxFollowers) break;

      // Scroll to load more
      window.scrollTo(0, document.body.scrollHeight);
      await sleep(CONFIG.scrollDelay);
      scrolls++;

      // Find all user cells and extract usernames
      const userCells = document.querySelectorAll('[data-testid="UserCell"]');
      userCells.forEach(cell => {
        if (CONFIG.maxFollowers > 0 && followers.size >= CONFIG.maxFollowers) return;
        const usernameEl = cell.querySelector('a[href^="/"]');
        if (usernameEl) {
          const href = usernameEl.getAttribute('href');
          const username = href.replace('/', '').toLowerCase();
          if (username && !username.includes('/')) {
            followers.add(username);
            if (!displayNames[username]) {
              const span = cell.querySelector('[dir="ltr"] span');
              const name = span ? span.textContent.trim() : '';
              if (name) displayNames[username] = name;
            }
          }
        }
      });

      console.log(`   Found ${followers.size} followers so far...`);

      if (followers.size === previousSize) {
        retries++;
      } else {
        retries = 0;
        previousSize = followers.size;
      }
    }

    return Array.from(followers);
  };

  // Accepts this script's snapshot ({ username, followers: [...], timestamp, count })
  // and the older scripts/twitter format ({ savedAt, count, followers: { user: name } }).
  const normalizeSnapshot = (data) => {
    if (!data || typeof data !== 'object' || Array.isArray(data) || !data.followers) return null;
    if (Array.isArray(data.followers)) {
      return {
        username: data.username,
        followers: data.followers,
        timestamp: data.timestamp || data.savedAt,
        count: data.count ?? data.followers.length,
        displayNames: data.displayNames || {},
      };
    }
    const followers = Object.keys(data.followers);
    return {
      username: data.username,
      followers,
      timestamp: data.timestamp || data.savedAt,
      count: data.count ?? followers.length,
      displayNames: data.followers,
    };
  };

  const loadPreviousFollowers = (username) => {
    for (const key of [STORAGE_KEY, ...CONFIG.legacyStorageKeys]) {
      try {
        const snapshot = normalizeSnapshot(JSON.parse(localStorage.getItem(key) || 'null'));
        if (!snapshot) continue;
        // Snapshots from the old scripts/twitter version carry no username.
        if (snapshot.username === undefined && key === STORAGE_KEY) snapshot.username = username;
        if (snapshot.username === username) return snapshot;
      } catch (e) {
        console.warn('Could not load previous data:', e);
      }
    }
    return null;
  };

  const saveFollowers = (followers, username) => {
    const names = {};
    followers.forEach(f => { if (displayNames[f]) names[f] = displayNames[f]; });
    const data = {
      username,
      followers,
      timestamp: new Date().toISOString(),
      count: followers.length,
      displayNames: names
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    return data;
  };

  const compareFollowers = (previous, current) => {
    const prevSet = new Set(previous.map(f => f.toLowerCase()));
    const currSet = new Set(current.map(f => f.toLowerCase()));

    const unfollowed = previous.filter(f => !currSet.has(f.toLowerCase()));
    const newFollowers = current.filter(f => !prevSet.has(f.toLowerCase()));

    return { unfollowed, newFollowers };
  };

  const formatDate = (isoString) => {
    return new Date(isoString).toLocaleString();
  };

  const downloadFile = (content, type, filename) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const run = async () => {
    const username = getCurrentUsername();
    console.log(`\n🐦 XActions Detector — Monitoring @${username}\n`);

    // Scrape current followers
    const currentFollowers = await scrapeFollowers();
    console.log(`\n✅ Found ${currentFollowers.length} total followers\n`);

    // Check for previous data
    const previousData = loadPreviousFollowers(username);

    if (previousData) {
      const previousNames = previousData.displayNames || {};
      const nameOf = (u) => previousNames[u] || displayNames[u] || previousNames[u.toLowerCase()] || u;
      const label = (u) => (CONFIG.showDisplayNames ? `@${u} (${nameOf(u)})` : `@${u}`);

      console.log(`📊 Comparing with snapshot from ${formatDate(previousData.timestamp)}`);
      console.log(`   Previous count: ${previousData.count}`);
      console.log(`   Current count: ${currentFollowers.length}`);
      console.log('');

      const { unfollowed, newFollowers } = compareFollowers(previousData.followers, currentFollowers);

      if (unfollowed.length > 0) {
        console.log(`\n🚨 ${unfollowed.length} PEOPLE UNFOLLOWED YOU:\n`);
        unfollowed.forEach((u, i) => {
          console.log(`   ${i + 1}. ${label(u)} — https://x.com/${u}`);
        });
      } else {
        console.log('✨ No one unfollowed you since last check!');
      }

      if (newFollowers.length > 0) {
        console.log(`\n🎉 ${newFollowers.length} NEW FOLLOWERS:\n`);
        newFollowers.forEach((u, i) => {
          console.log(`   ${i + 1}. ${label(u)} — https://x.com/${u}`);
        });
      } else {
        console.log('📭 No new followers since last check.');
      }

      const now = new Date().toISOString();
      const day = now.split('T')[0];

      // Offer download
      if (CONFIG.autoDownload) {
        if (CONFIG.downloadFormat === 'report' && (unfollowed.length > 0 || newFollowers.length > 0)) {
          let report = 'UNFOLLOWER DETECTION REPORT\n';
          report += `${'='.repeat(50)}\n`;
          report += `Generated: ${now}\n`;
          report += `Previous snapshot: ${previousData.timestamp}\n`;
          report += `Previous count: ${previousData.count}\n`;
          report += `Current count: ${currentFollowers.length}\n`;
          report += `${'='.repeat(50)}\n\n`;
          if (unfollowed.length > 0) {
            report += `UNFOLLOWERS (${unfollowed.length}):\n`;
            report += `${'-'.repeat(30)}\n`;
            unfollowed.forEach((u, i) => {
              report += `${i + 1}. @${u} (${nameOf(u)})\n`;
              report += `   https://x.com/${u}\n`;
            });
            report += '\n';
          }
          if (newFollowers.length > 0) {
            report += `NEW FOLLOWERS (${newFollowers.length}):\n`;
            report += `${'-'.repeat(30)}\n`;
            newFollowers.forEach((u, i) => {
              report += `${i + 1}. @${u} (${nameOf(u)})\n`;
            });
          }
          downloadFile(report, 'text/plain', `unfollowers_${day}.txt`);
          console.log('\n📥 Downloaded the unfollower report!');
        } else if (CONFIG.downloadFormat === 'json' && unfollowed.length > 0) {
          downloadFile(
            JSON.stringify({ unfollowers: unfollowed, newFollowers, detectedAt: now, previousSnapshot: previousData.timestamp }, null, 2),
            'application/json',
            `xactions-unfollowers-${day}.json`
          );
          console.log('\n📥 Downloaded list of unfollowers!');
        } else if (CONFIG.downloadFormat !== 'report' && CONFIG.downloadFormat !== 'json' && unfollowed.length > 0) {
          downloadFile(unfollowed.join('\n'), 'text/plain', `unfollowers-${day}.txt`);
          console.log('\n📥 Downloaded list of unfollowers!');
        }
      }

      window.unfollowerReport = {
        timestamp: now,
        previous: previousData.count,
        current: currentFollowers.length,
        unfollowers: unfollowed.map(u => ({ username: u, displayName: nameOf(u) })),
        newFollowers: newFollowers.map(u => ({ username: u, displayName: nameOf(u) }))
      };
      console.log('\n💡 Access data via: window.unfollowerReport');
    } else {
      console.log('📸 First scan! Saving snapshot of your followers...');
      console.log('   Run this script again later to detect changes.');
    }

    // Save current state
    const saved = saveFollowers(currentFollowers, username);
    if (!previousData) window.followerSnapshot = saved;
    console.log(`\n💾 Snapshot saved at ${formatDate(saved.timestamp)}`);
    console.log('   Run this script again anytime to check for changes!\n');
  };

  run();
})();

});
  register("dmCalls", function(){
(() => {
  'use strict';

  const CONFIG = {
    // ── Target ───────────────────────────────────────────────
    username: 'target_user',     // Username to call (without @)
    callType: 'audio',           // 'audio' or 'video'

    // ── Timing ───────────────────────────────────────────────
    navigationDelay: 3000,       // Wait for page loads
    actionDelay: 2000,           // Wait between actions
    scrollDelay: 1500,           // Wait between scrolls when searching

    // ── Search ───────────────────────────────────────────────
    maxScrollAttempts: 20,       // Max scrolls to find conversation

    // ── Safety ───────────────────────────────────────────────
    dryRun: true,                // Set to false to actually initiate call
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  const SEL = {
    messagesLink:   'a[href="/messages"]',
    conversation:   '[data-testid="conversation"]',
    audioCall:      '[data-testid="dmAudioCall"]',
    videoCall:      '[data-testid="dmVideoCall"]',
    searchDM:       '[data-testid="SearchBox_Search_Input"]',
    dmHeader:       '[data-testid="DmActivityContainer"]',
    conversationName: '[data-testid="conversationName"]',
  };

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const $ = (s) => document.querySelector(s);
  const $$ = (s) => [...document.querySelectorAll(s)];

  const waitForSelector = async (selector, timeout = 10000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const el = $(selector);
      if (el) return el;
      await sleep(200);
    }
    return null;
  };

  const stats = {
    conversationFound: false,
    callInitiated: false,
    startTime: Date.now(),
  };

  const findConversation = async () => {
    console.log(`🔍 Looking for conversation with @${CONFIG.username}...`);

    // Try searching in DM search if available
    const searchInput = $(SEL.searchDM);
    if (searchInput) {
      searchInput.focus();
      searchInput.value = '';
      document.execCommand('insertText', false, CONFIG.username);
      searchInput.dispatchEvent(new Event('input', { bubbles: true }));
      await sleep(CONFIG.navigationDelay);
    }

    let scrollAttempts = 0;
    while (scrollAttempts < CONFIG.maxScrollAttempts) {
      const conversations = $$(SEL.conversation);

      for (const conv of conversations) {
        const text = conv.textContent.toLowerCase();
        if (text.includes(CONFIG.username.toLowerCase())) {
          console.log(`✅ Found conversation with @${CONFIG.username}`);
          return conv;
        }
      }

      // Scroll the conversation list
      const conversationList = document.querySelector('[data-testid="DMDrawer"]') ||
                               document.querySelector('section[role="region"]') ||
                               document.querySelector('[aria-label="Timeline: Messages"]');
      if (conversationList) {
        conversationList.scrollTop += 500;
      } else {
        window.scrollBy(0, 500);
      }

      await sleep(CONFIG.scrollDelay);
      scrollAttempts++;
    }

    return null;
  };

  const run = async () => {
    const W = 60;
    console.log('╔' + '═'.repeat(W) + '╗');
    console.log('║  📞 DM AUDIO & VIDEO CALLS' + ' '.repeat(W - 29) + '║');
    console.log('║  by nichxbt — v1.0' + ' '.repeat(W - 21) + '║');
    console.log('╚' + '═'.repeat(W) + '╝');

    if (CONFIG.dryRun) {
      console.log('⚠️ DRY RUN MODE — set CONFIG.dryRun = false to actually call');
    }

    const validTypes = ['audio', 'video'];
    if (!validTypes.includes(CONFIG.callType)) {
      console.log(`❌ Invalid callType: "${CONFIG.callType}". Use 'audio' or 'video'`);
      return;
    }

    console.log(`📋 Target: @${CONFIG.username}`);
    console.log(`📞 Call type: ${CONFIG.callType}`);

    const sessionKey = 'xactions_dmCalls';
    sessionStorage.setItem(sessionKey, JSON.stringify({ status: 'running', ...stats }));

    // Navigate to messages if not already there
    if (!window.location.pathname.startsWith('/messages')) {
      console.log('🔄 Navigating to messages...');
      const msgLink = $(SEL.messagesLink);
      if (msgLink) {
        if (!CONFIG.dryRun) {
          msgLink.click();
          await sleep(CONFIG.navigationDelay);
        }
      } else {
        console.log('⚠️ Navigating directly to /messages...');
        if (!CONFIG.dryRun) {
          window.location.href = 'https://x.com/messages';
          return; // Page will reload
        }
      }
    }

    // Find and open the conversation
    const conversation = await findConversation();
    if (!conversation) {
      console.log(`❌ Could not find conversation with @${CONFIG.username}`);
      console.log('💡 Make sure you have an existing DM conversation with this user');
      return;
    }

    stats.conversationFound = true;

    if (!CONFIG.dryRun) {
      conversation.click();
      await sleep(CONFIG.navigationDelay);
    }
    console.log('✅ Opened conversation');

    // Find and click the call button
    const callSelector = CONFIG.callType === 'audio' ? SEL.audioCall : SEL.videoCall;
    const callButton = await waitForSelector(callSelector);

    if (!callButton) {
      console.log(`❌ Could not find ${CONFIG.callType} call button`);
      console.log('💡 DM calls may not be available for this conversation');
      console.log('💡 Both parties must have DM calls enabled in settings');
      return;
    }

    console.log(`🔄 Initiating ${CONFIG.callType} call with @${CONFIG.username}...`);

    if (!CONFIG.dryRun) {
      callButton.click();
      await sleep(CONFIG.actionDelay);
    }

    stats.callInitiated = true;

    // Final summary
    console.log('');
    console.log('╔' + '═'.repeat(W) + '╗');
    console.log('║  📊 DM CALL SUMMARY' + ' '.repeat(W - 21) + '║');
    console.log('╚' + '═'.repeat(W) + '╝');
    console.log(`✅ Conversation found: ${stats.conversationFound}`);
    console.log(`📞 ${CONFIG.callType.charAt(0).toUpperCase() + CONFIG.callType.slice(1)} call initiated: ${stats.callInitiated}`);
    console.log(`⏱️ Duration: ${((Date.now() - stats.startTime) / 1000).toFixed(1)}s`);

    sessionStorage.setItem(sessionKey, JSON.stringify({ status: 'complete', ...stats }));
  };

  run();
})();

});
  register("dmManager", function(){
(() => {
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  // =============================================
  // CONFIGURATION
  // =============================================
  const CONFIG = {
    action: 'send',           // 'send' | 'export'
    targetUser: '',           // Username to DM (for 'send')
    message: '',              // Message to send
    maxConversations: 20,     // Max conversations to export
    scrollDelay: 1500,
    dryRun: true,             // SET FALSE TO EXECUTE
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}

  // =============================================

  const download = (data, filename) => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }));
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    console.log(`📥 Downloaded: ${filename}`);
  };

  const sendDM = async () => {
    if (!CONFIG.targetUser || !CONFIG.message) {
      console.error('❌ Set CONFIG.targetUser and CONFIG.message first!');
      return;
    }

    console.log(`💬 Sending DM to @${CONFIG.targetUser}...`);

    if (CONFIG.dryRun) {
      console.log(`   📝 Would send to @${CONFIG.targetUser}: "${CONFIG.message.substring(0, 80)}..."`);
      return;
    }

    try {
      // Click new DM
      const newBtn = document.querySelector('[data-testid="NewDM_Button"]');
      if (newBtn) { newBtn.click(); await sleep(1500); }

      // Search user
      const searchInput = document.querySelector('[data-testid="searchPeople"]');
      if (!searchInput) { console.error('❌ Search input not found'); return; }
      searchInput.focus();
      document.execCommand('insertText', false, CONFIG.targetUser);
      await sleep(2000);

      // Select user
      const cells = document.querySelectorAll('[data-testid="TypeaheadUser"], [data-testid="UserCell"]');
      let found = false;
      for (const cell of cells) {
        if (cell.textContent.toLowerCase().includes(CONFIG.targetUser.toLowerCase())) {
          cell.click();
          found = true;
          break;
        }
      }
      if (!found) { console.error(`❌ @${CONFIG.targetUser} not found`); return; }
      await sleep(1000);

      // Click next
      const nextBtn = document.querySelector('[data-testid="nextButton"]');
      if (nextBtn) { nextBtn.click(); await sleep(1500); }

      // Type and send
      const msgInput = document.querySelector('[data-testid="dmComposerTextInput"]');
      if (msgInput) {
        msgInput.focus();
        document.execCommand('insertText', false, CONFIG.message);
        await sleep(500);

        const sendBtn = document.querySelector('[data-testid="dmComposerSendButton"]');
        if (sendBtn) { sendBtn.click(); await sleep(1000); }
      }

      console.log(`✅ DM sent to @${CONFIG.targetUser}`);
    } catch (e) {
      console.error('❌ Failed to send DM:', e.message);
    }
  };

  const exportConversations = async () => {
    console.log(`📥 Exporting up to ${CONFIG.maxConversations} conversations...`);

    const conversations = [];
    let retries = 0;

    while (conversations.length < CONFIG.maxConversations && retries < 5) {
      const prevSize = conversations.length;

      document.querySelectorAll('[data-testid="conversation"]').forEach(conv => {
        const name = conv.querySelector('[dir="ltr"] span')?.textContent || '';
        const lastMsg = conv.querySelector('[data-testid="lastMessage"]')?.textContent || conv.querySelector('[dir="auto"]')?.textContent || '';
        const time = conv.querySelector('time')?.getAttribute('datetime') || '';
        const unread = !!conv.querySelector('[data-testid="unread"]');

        if (!conversations.find(c => c.name === name && c.time === time)) {
          conversations.push({ name, lastMessage: lastMsg.substring(0, 200), time, unread });
        }
      });

      if (conversations.length === prevSize) retries++;
      else retries = 0;

      window.scrollTo(0, document.body.scrollHeight);
      await sleep(CONFIG.scrollDelay);
    }

    const data = { exportedAt: new Date().toISOString(), count: conversations.length, conversations };
    download(data, `xactions-conversations-${new Date().toISOString().slice(0, 10)}.json`);
    console.log(`✅ Exported ${conversations.length} conversations`);
  };

  const run = async () => {
    console.log('💬 DM MANAGER — XActions by nichxbt\n');

    if (!window.location.href.includes('/messages')) {
      console.error('❌ Navigate to x.com/messages first!');
      return;
    }

    if (CONFIG.action === 'send') await sendDM();
    else if (CONFIG.action === 'export') await exportConversations();
    else console.error(`❌ Unknown action: ${CONFIG.action}`);

    console.log('\n🏁 Done!');
  };

  run();
})();

});
  register("downloadAccountData", function(){
(() => {
  const CONFIG = {
    checkInterval: 30000, // Check every 30 seconds
    maxChecks: 120,       // Stop after 60 minutes
    autoDownload: true,
    monitorWhilePreparing: false, // Keep checking every checkInterval while the archive is prepared
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  const run = async () => {
    console.log('📦 DOWNLOAD ACCOUNT DATA - XActions by nichxbt');

    if (!window.location.href.includes('/download_your_data') && !window.location.href.includes('/your_twitter_data')) {
      console.error('❌ Navigate to x.com/settings/download_your_data first!');
      console.log('📍 Or go to: Settings > Your account > Download an archive of your data');
      return;
    }

    console.log('ℹ️ This script helps trigger and monitor Twitter\'s official data export.\n');

    // Look for the request button
    const buttons = document.querySelectorAll('button, [role="button"]');
    let requestBtn = null;
    let downloadBtn = null;

    for (const btn of buttons) {
      const text = btn.textContent.toLowerCase();
      if (text.includes('request') && text.includes('archive')) {
        requestBtn = btn;
      }
      if (text.includes('download') && (text.includes('archive') || text.includes('data'))) {
        downloadBtn = btn;
      }
    }

    if (downloadBtn) {
      console.log('✅ Your data archive is ready!');
      if (CONFIG.autoDownload) {
        downloadBtn.click();
        console.log('📥 Download started...');
      } else {
        console.log('💡 Click the download button to save your archive.');
      }
      return;
    }

    if (requestBtn) {
      console.log('📤 Requesting data archive...');
      requestBtn.click();
      await sleep(2000);
      console.log('✅ Archive requested! Twitter will prepare your data.');
      console.log('⏳ This usually takes 24-48 hours.');
      console.log('📧 You\'ll receive an email when it\'s ready.');
      console.log('\n💡 Come back to this page later to download.');
    } else {
      console.log('⏳ Checking current status...');

      // Look for status indicators
      const pageText = document.body.textContent.toLowerCase();
      if ((pageText.includes('preparing') || pageText.includes('processing')) && CONFIG.monitorWhilePreparing) {
        console.log('🔄 Your data is being prepared.');
        console.log(`⏳ Will check every ${CONFIG.checkInterval / 1000}s (up to ${Math.round(CONFIG.maxChecks * CONFIG.checkInterval / 60000)} min)...\n`);

        let checks = 0;
        while (checks < CONFIG.maxChecks) {
          await sleep(CONFIG.checkInterval);
          checks++;

          let readyBtn = null;
          for (const btn of document.querySelectorAll('button, [role="button"]')) {
            const text = btn.textContent.toLowerCase();
            if (text.includes('download') && (text.includes('archive') || text.includes('data'))) readyBtn = btn;
          }
          if (readyBtn) {
            console.log('🎉 Archive is ready!');
            if (CONFIG.autoDownload) {
              readyBtn.click();
              console.log('📥 Download started!');
            } else {
              console.log('💡 Click the download button to save.');
            }
            return;
          }

          if (checks % 6 === 0) {
            console.log(`   ⏳ Still waiting... (${checks}/${CONFIG.maxChecks} checks)`);
          }
        }

        console.log('⏱️ Max checks reached. Archive may not be ready yet.');
        console.log('💡 Try again later or check your email for a notification.');
      } else if (pageText.includes('preparing') || pageText.includes('processing')) {
        console.log('🔄 Your data is being prepared. Check back later.');
        console.log('💡 Set CONFIG.monitorWhilePreparing = true to keep checking from this tab.');
      } else if (pageText.includes('expired')) {
        console.log('⚠️ Previous archive has expired. You need to request a new one.');
      } else {
        console.log('ℹ️ Could not determine status. Look for the "Request archive" button on the page.');
        console.log('📍 Settings > Your account > Download an archive of your data');
      }
    }
  };

  run();
})();

});
  register("editPost", function(){
(() => {
  'use strict';

  const CONFIG = {
    // ── Mode: 'edit' or 'undo' ──
    mode: 'edit',               // 'edit' = edit an existing post, 'undo' = undo last post

    // ── Edit Mode Settings ──
    postUrl: '',                // Full URL of the post to edit, e.g. 'https://x.com/nichxbt/status/123456789'
    newText: '',                // New text to replace the post content with

    // ── Undo Mode Settings ──
    // After posting, the undo banner appears for ~30 seconds (Premium only)
    // Set mode to 'undo' and run this script immediately after posting

    // ── Timing ──
    minDelay: 1000,
    maxDelay: 2000,
    navigationDelay: 3000,      // Wait for page/modal to load
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  // ── Selectors ──
  const SEL = {
    caret:          '[data-testid="caret"]',
    editTweet:      '[data-testid="editTweet"]',
    tweetTextarea:  '[data-testid="tweetTextarea_0"]',
    tweetButton:    '[data-testid="tweetButton"]',
    undoTweet:      '[data-testid="undoTweet"]',
    tweet:          'article[data-testid="tweet"]',
    menuItem:       '[role="menuitem"]',
  };

  // ── Utilities ──
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const randomDelay = () => Math.floor(Math.random() * (CONFIG.maxDelay - CONFIG.minDelay + 1)) + CONFIG.minDelay;

  const waitForElement = async (selector, timeout = 10000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const el = document.querySelector(selector);
      if (el) return el;
      await sleep(200);
    }
    return null;
  };

  // ── Edit Post ──
  const editPost = async () => {
    if (!CONFIG.postUrl) {
      console.error('❌ Please set CONFIG.postUrl to the URL of the post you want to edit.');
      return;
    }
    if (!CONFIG.newText) {
      console.error('❌ Please set CONFIG.newText to the replacement text.');
      return;
    }

    // Navigate to the post if not already there
    if (!window.location.href.includes(CONFIG.postUrl.replace('https://x.com', ''))) {
      console.log('🔄 Navigating to post...');
      window.location.href = CONFIG.postUrl;
      await sleep(CONFIG.navigationDelay);
    }

    // Find and click the caret (three-dot menu) on the tweet
    console.log('🔄 Opening post menu...');
    const tweet = await waitForElement(SEL.tweet);
    if (!tweet) {
      console.error('❌ Could not find the tweet on this page.');
      return;
    }

    const caret = tweet.querySelector(SEL.caret);
    if (!caret) {
      console.error('❌ Could not find the menu button (caret) on this tweet.');
      return;
    }
    caret.click();
    await sleep(randomDelay());

    // Click "Edit post" from the dropdown
    console.log('🔄 Clicking "Edit post"...');
    const editBtn = await waitForElement(SEL.editTweet);
    if (!editBtn) {
      // Fallback: search menu items by text
      const menuItems = document.querySelectorAll(SEL.menuItem);
      let found = false;
      for (const item of menuItems) {
        if (item.textContent.toLowerCase().includes('edit')) {
          item.click();
          found = true;
          break;
        }
      }
      if (!found) {
        console.error('❌ "Edit post" option not found. Make sure you own this post and have edit privileges.');
        return;
      }
    } else {
      editBtn.click();
    }
    await sleep(CONFIG.navigationDelay);

    // Clear existing text and type new text
    console.log('🔄 Editing post text...');
    const textarea = await waitForElement(SEL.tweetTextarea);
    if (!textarea) {
      console.error('❌ Could not find the text editor.');
      return;
    }

    // Focus and select all existing text
    textarea.focus();
    await sleep(300);

    // Select all text and replace
    document.execCommand('selectAll', false, null);
    await sleep(200);
    document.execCommand('insertText', false, CONFIG.newText);
    await sleep(randomDelay());

    // Click the save/update button
    console.log('🔄 Saving edited post...');
    const saveBtn = await waitForElement(SEL.tweetButton);
    if (!saveBtn) {
      console.error('❌ Could not find the save button.');
      return;
    }
    saveBtn.click();
    await sleep(randomDelay());

    console.log('✅ Post edited successfully!');
    console.log(`   New text: "${CONFIG.newText}"`);
  };

  // ── Undo Post ──
  const undoPost = async () => {
    console.log('🔄 Looking for undo button...');
    console.log('⚠️  Undo is only available for ~30 seconds after posting (Premium feature).');

    const undoBtn = await waitForElement(SEL.undoTweet, 5000);
    if (!undoBtn) {
      console.error('❌ Undo button not found. The undo window may have expired (30s limit).');
      console.log('💡 Tip: Run this script immediately after posting to catch the undo window.');
      return;
    }

    undoBtn.click();
    await sleep(randomDelay());
    console.log('✅ Post undone successfully! The tweet has been retracted.');
  };

  // ── Main ──
  const run = async () => {
    console.log('═══════════════════════════════════════');
    console.log('✏️  XActions — Edit / Undo Post');
    console.log('═══════════════════════════════════════');

    if (CONFIG.mode === 'undo') {
      await undoPost();
    } else if (CONFIG.mode === 'edit') {
      await editPost();
    } else {
      console.error(`❌ Invalid mode: "${CONFIG.mode}". Use 'edit' or 'undo'.`);
    }

    console.log('═══════════════════════════════════════');
    console.log('🏁 Done! — by nichxbt');
  };

  run();
})();

});
  register("encryptedDM", function(){
(() => {
  'use strict';

  const CONFIG = {
    // ── Action ───────────────────────────────────────────────
    action: 'send',              // 'send', 'check', or 'enable'
    //   send   — send an encrypted message to a user
    //   check  — check if current conversation is encrypted
    //   enable — enable encrypted mode for current conversation

    // ── Message (for 'send' action) ─────────────────────────
    username: 'target_user',     // Username to message (without @)
    message: 'This is a secret encrypted message 🔐',

    // ── Timing ───────────────────────────────────────────────
    navigationDelay: 3000,
    actionDelay: 2000,
    typeCharDelay: 50,

    // ── Safety ───────────────────────────────────────────────
    dryRun: true,                // Set to false to actually send
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  const SEL = {
    encryptedDM:      '[data-testid="encryptedDM"]',
    composerInput:    '[data-testid="dmComposerTextInput"]',
    sendButton:       '[data-testid="dmComposerSendButton"]',
    lockIcon:         '[data-testid="lockIcon"]',
    newDM:            '[data-testid="NewDM_Button"]',
    searchPeople:     '[data-testid="searchPeople"]',
    typeaheadUser:    '[data-testid="TypeaheadUser"]',
    nextButton:       '[data-testid="nextButton"]',
    conversation:     '[data-testid="conversation"]',
    dmHeader:         '[data-testid="DmActivityContainer"]',
  };

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const $ = (s) => document.querySelector(s);
  const $$ = (s) => [...document.querySelectorAll(s)];

  const waitForSelector = async (selector, timeout = 10000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const el = $(selector);
      if (el) return el;
      await sleep(200);
    }
    return null;
  };

  const typeText = async (element, text) => {
    element.focus();
    for (const char of text) {
      document.execCommand('insertText', false, char);
      element.dispatchEvent(new InputEvent('input', { bubbles: true, data: char, inputType: 'insertText' }));
      await sleep(CONFIG.typeCharDelay);
    }
  };

  const stats = {
    action: CONFIG.action,
    encryptionEnabled: false,
    isEncrypted: null,
    messageSent: false,
    startTime: Date.now(),
  };

  const checkEncryption = async () => {
    console.log('🔍 Checking encryption status of current conversation...');

    const lockIcon = $(SEL.lockIcon);
    const encryptedIndicator = $(SEL.encryptedDM);

    // Look for encryption indicators in the conversation header
    const header = $(SEL.dmHeader) || document.querySelector('[data-testid="DMConversationHeader"]');
    const hasEncryptionBadge = header ? header.querySelector('svg[aria-label*="ncrypt"], [data-testid="lockIcon"]') : null;

    if (lockIcon || encryptedIndicator || hasEncryptionBadge) {
      stats.isEncrypted = true;
      console.log('🔒 This conversation IS encrypted');
      console.log('✅ End-to-end encryption is active');
    } else {
      stats.isEncrypted = false;
      console.log('🔓 This conversation is NOT encrypted');
      console.log('💡 Both users must be verified (Premium) to use encrypted DMs');
    }

    return stats.isEncrypted;
  };

  const enableEncryption = async () => {
    console.log('🔄 Enabling encrypted mode for this conversation...');

    const encryptBtn = await waitForSelector(SEL.encryptedDM);
    if (!encryptBtn) {
      console.log('❌ Could not find encrypted DM toggle');
      console.log('💡 Make sure you are in a DM conversation');
      console.log('💡 Both users must have Premium for encrypted DMs');
      return false;
    }

    if (!CONFIG.dryRun) {
      encryptBtn.click();
      await sleep(CONFIG.actionDelay);
    }

    stats.encryptionEnabled = true;
    console.log('✅ Encrypted mode enabled');
    return true;
  };

  const sendEncryptedMessage = async () => {
    console.log(`🔄 Sending encrypted message to @${CONFIG.username}...`);

    // If not already in messages, navigate there
    if (!window.location.pathname.startsWith('/messages')) {
      console.log('🔄 Navigating to messages...');
      if (!CONFIG.dryRun) {
        window.location.href = 'https://x.com/messages';
        return;
      }
    }

    // Start a new DM or find existing conversation
    console.log('🔄 Opening new encrypted conversation...');
    const newDMBtn = await waitForSelector(SEL.newDM);
    if (!newDMBtn) {
      console.log('❌ Could not find New DM button');
      return;
    }

    if (!CONFIG.dryRun) {
      newDMBtn.click();
      await sleep(CONFIG.actionDelay);
    }

    // Enable encrypted mode before selecting recipient
    const encryptBtn = await waitForSelector(SEL.encryptedDM, 5000);
    if (encryptBtn) {
      console.log('🔒 Enabling encryption for this conversation...');
      if (!CONFIG.dryRun) {
        encryptBtn.click();
        await sleep(CONFIG.actionDelay);
      }
      stats.encryptionEnabled = true;
    } else {
      console.log('⚠️ Encrypted DM toggle not found — may not be available');
    }

    // Search for the user
    console.log(`🔍 Searching for @${CONFIG.username}...`);
    const searchInput = await waitForSelector(SEL.searchPeople);
    if (!searchInput) {
      console.log('❌ Could not find people search input');
      return;
    }

    if (!CONFIG.dryRun) {
      searchInput.focus();
      await typeText(searchInput, CONFIG.username);
      await sleep(2000);

      const userResult = await waitForSelector(SEL.typeaheadUser);
      if (!userResult) {
        console.log(`❌ Could not find @${CONFIG.username} in results`);
        return;
      }

      userResult.click();
      await sleep(CONFIG.actionDelay);

      // Click Next
      const nextBtn = await waitForSelector(SEL.nextButton);
      if (!nextBtn) {
        console.log('❌ Could not find Next button');
        return;
      }
      nextBtn.click();
      await sleep(CONFIG.navigationDelay);
    }

    // Type and send the message
    console.log('✍️ Typing encrypted message...');
    if (!CONFIG.dryRun) {
      const composerInput = await waitForSelector(SEL.composerInput);
      if (!composerInput) {
        console.log('❌ Could not find message composer');
        return;
      }

      await typeText(composerInput, CONFIG.message);
      await sleep(1000);

      const sendBtn = await waitForSelector(SEL.sendButton);
      if (!sendBtn) {
        console.log('❌ Could not find send button');
        return;
      }
      sendBtn.click();
      await sleep(CONFIG.actionDelay);
    }

    stats.messageSent = true;
    console.log('✅ Encrypted message sent!');
  };

  const run = async () => {
    const W = 60;
    console.log('╔' + '═'.repeat(W) + '╗');
    console.log('║  🔒 ENCRYPTED DIRECT MESSAGES' + ' '.repeat(W - 32) + '║');
    console.log('║  by nichxbt — v1.0' + ' '.repeat(W - 21) + '║');
    console.log('╚' + '═'.repeat(W) + '╝');

    if (CONFIG.dryRun) {
      console.log('⚠️ DRY RUN MODE — set CONFIG.dryRun = false to actually act');
    }

    const validActions = ['send', 'check', 'enable'];
    if (!validActions.includes(CONFIG.action)) {
      console.log(`❌ Invalid action: "${CONFIG.action}". Use: ${validActions.join(', ')}`);
      return;
    }

    console.log(`📋 Action: ${CONFIG.action}`);
    const sessionKey = 'xactions_encryptedDM';
    sessionStorage.setItem(sessionKey, JSON.stringify({ status: 'running', ...stats }));

    switch (CONFIG.action) {
      case 'check':
        await checkEncryption();
        break;
      case 'enable':
        await enableEncryption();
        break;
      case 'send':
        await sendEncryptedMessage();
        break;
    }

    // Final summary
    console.log('');
    console.log('╔' + '═'.repeat(W) + '╗');
    console.log('║  📊 ENCRYPTED DM SUMMARY' + ' '.repeat(W - 27) + '║');
    console.log('╚' + '═'.repeat(W) + '╝');
    console.log(`🔧 Action: ${CONFIG.action}`);
    if (stats.isEncrypted !== null) {
      console.log(`🔒 Encrypted: ${stats.isEncrypted}`);
    }
    if (stats.encryptionEnabled) {
      console.log('✅ Encryption enabled');
    }
    if (stats.messageSent) {
      console.log('✅ Message sent');
    }
    console.log(`⏱️ Duration: ${((Date.now() - stats.startTime) / 1000).toFixed(1)}s`);

    sessionStorage.setItem(sessionKey, JSON.stringify({ status: 'complete', ...stats }));
  };

  run();
})();

});
  register("engagementAnalytics", function(){
(() => {
  const CONFIG = {
    maxPosts: 50,
    scrollDelay: 1500,
    maxScrollAttempts: 30,
    maxRetries: 3,
    exportResults: true,
    ownerOnly: false,          // Only count posts by the profile owner (skips reposts of others)
    detailedReport: false,     // Also print averages per post, top by retweets, top by engagement rate, worst 3, with URLs
    saveToLocalStorage: false, // Save the analysis under xactions_engagement_<username> to compare over time
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  const $tweet = 'article[data-testid="tweet"]';
  const $tweetText = '[data-testid="tweetText"]';
  const $like = '[data-testid="like"], [data-testid="unlike"]';
  const $retweet = '[data-testid="retweet"], [data-testid="unretweet"]';
  const $reply = '[data-testid="reply"]';
  const $views = 'a[href*="/analytics"]';

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  const parseCount = (str) => {
    if (!str) return 0;
    str = str.replace(/,/g, '').trim();
    const match = str.match(/([\d.]+)([KMB])?/i);
    if (match) {
      let num = parseFloat(match[1]);
      const multipliers = { 'K': 1000, 'M': 1000000, 'B': 1000000000 };
      if (match[2]) num *= multipliers[match[2].toUpperCase()];
      return Math.round(num);
    }
    return 0;
  };

  const getUsername = () => {
    const match = window.location.pathname.match(/^\/([^\/]+)/);
    return match ? match[1] : null;
  };

  const run = async () => {
    console.log('📊 ENGAGEMENT ANALYTICS - XActions by nichxbt');

    const username = getUsername();
    if (!username || ['home', 'explore', 'notifications', 'messages', 'i'].includes(username)) {
      console.error('❌ Navigate to a profile page first! (x.com/YOUR_USERNAME)');
      return;
    }

    console.log(`📊 Analyzing @${username}'s engagement...\n`);

    const posts = new Map();
    let retries = 0;
    let scrollCount = 0;

    while (posts.size < CONFIG.maxPosts && scrollCount < CONFIG.maxScrollAttempts && retries < CONFIG.maxRetries) {
      const prevSize = posts.size;

      document.querySelectorAll($tweet).forEach(tweet => {
        if (CONFIG.ownerOnly) {
          let isOwner = false;
          tweet.querySelectorAll('a[href^="/"]').forEach(link => {
            if (link.getAttribute('href')?.toLowerCase() === `/${username.toLowerCase()}`) isOwner = true;
          });
          if (!isOwner) return;
        }

        const linkEl = tweet.querySelector('a[href*="/status/"]');
        if (!linkEl) return;
        const tweetUrl = linkEl.href;
        if (posts.has(tweetUrl)) return;

        const textEl = tweet.querySelector($tweetText);
        const likeEl = tweet.querySelector($like);
        const rtEl = tweet.querySelector($retweet);
        const replyEl = tweet.querySelector($reply);
        const viewEl = tweet.querySelector($views);
        const timeEl = tweet.querySelector('time');

        const likes = parseCount(likeEl?.getAttribute('aria-label') || '0');
        const retweets = parseCount(rtEl?.getAttribute('aria-label') || '0');
        const replies = parseCount(replyEl?.getAttribute('aria-label') || '0');
        const views = parseCount(viewEl?.textContent || '0');

        posts.set(tweetUrl, {
          text: textEl?.textContent?.substring(0, 100) || '',
          url: tweetUrl,
          timestamp: timeEl?.dateTime || '',
          likes,
          retweets,
          replies,
          views,
          engagement: likes + retweets + replies,
          engagementRate: views > 0 ? ((likes + retweets + replies) / views * 100).toFixed(2) : '0',
        });
      });

      if (posts.size === prevSize) retries++;
      else retries = 0;

      scrollCount++;
      window.scrollTo(0, document.body.scrollHeight);
      await sleep(CONFIG.scrollDelay);
    }

    // Analysis
    const postsArray = [...posts.values()];
    if (postsArray.length === 0) {
      console.error('❌ No posts found. Make sure you\'re on the correct profile page.');
      return;
    }
    const totalLikes = postsArray.reduce((s, p) => s + p.likes, 0);
    const totalRetweets = postsArray.reduce((s, p) => s + p.retweets, 0);
    const totalReplies = postsArray.reduce((s, p) => s + p.replies, 0);
    const totalViews = postsArray.reduce((s, p) => s + p.views, 0);
    const totalEngagement = totalLikes + totalRetweets + totalReplies;
    const avgEngRate = totalViews > 0 ? (totalEngagement / totalViews * 100).toFixed(2) : '0';

    const topByLikes = [...postsArray].sort((a, b) => b.likes - a.likes).slice(0, 5);
    const topByEngagement = [...postsArray].sort((a, b) => b.engagement - a.engagement).slice(0, 5);
    const topByViews = [...postsArray].sort((a, b) => b.views - a.views).slice(0, 5);

    // Best posting times analysis
    const hourCounts = {};
    const dayCounts = {};
    postsArray.forEach(p => {
      if (p.timestamp) {
        const d = new Date(p.timestamp);
        const hour = d.getHours();
        const day = d.toLocaleDateString('en-US', { weekday: 'long' });
        hourCounts[hour] = (hourCounts[hour] || 0) + p.engagement;
        dayCounts[day] = (dayCounts[day] || 0) + p.engagement;
      }
    });

    const bestHour = Object.entries(hourCounts).sort((a, b) => b[1] - a[1])[0];
    const bestDay = Object.entries(dayCounts).sort((a, b) => b[1] - a[1])[0];

    console.log('╔════════════════════════════════════════════════════════════╗');
    console.log('║  📊 ENGAGEMENT REPORT                                      ║');
    console.log('╚════════════════════════════════════════════════════════════╝');
    console.log(`\n📈 OVERVIEW (${postsArray.length} posts analyzed)`);
    console.log(`   ❤️  Total likes:     ${totalLikes.toLocaleString()}`);
    console.log(`   🔄 Total retweets:  ${totalRetweets.toLocaleString()}`);
    console.log(`   💬 Total replies:   ${totalReplies.toLocaleString()}`);
    console.log(`   👁️  Total views:     ${totalViews.toLocaleString()}`);
    console.log(`   📊 Avg engagement:  ${avgEngRate}%`);
    console.log(`   📊 Avg likes/post:  ${(totalLikes / postsArray.length).toFixed(1)}`);

    if (bestHour) console.log(`\n⏰ Best posting hour: ${bestHour[0]}:00 (${bestHour[1]} total engagement)`);
    if (bestDay) console.log(`📅 Best posting day: ${bestDay[0]} (${bestDay[1]} total engagement)`);

    console.log('\n🏆 TOP 5 BY LIKES:');
    topByLikes.forEach((p, i) => {
      console.log(`   ${i + 1}. ❤️ ${p.likes} | "${p.text.substring(0, 50)}..."`);
    });

    console.log('\n🏆 TOP 5 BY ENGAGEMENT:');
    topByEngagement.forEach((p, i) => {
      console.log(`   ${i + 1}. 📊 ${p.engagement} | "${p.text.substring(0, 50)}..."`);
    });

    if (CONFIG.detailedReport) {
      const n = postsArray.length;
      const formatNum = (v) => {
        if (v >= 1000000) return (v / 1000000).toFixed(1) + 'M';
        if (v >= 1000) return (v / 1000).toFixed(1) + 'K';
        return Math.round(v).toString();
      };

      console.log('\n📊 AVERAGES PER POST:');
      console.log(`   ❤️  Likes:    ${(totalLikes / n).toFixed(1)}`);
      console.log(`   🔄 Retweets: ${(totalRetweets / n).toFixed(1)}`);
      console.log(`   💬 Replies:  ${(totalReplies / n).toFixed(1)}`);
      console.log(`   👁️  Views:    ${formatNum(totalViews / n)}`);

      console.log('\n🏆 TOP 5 BY LIKES (with links):');
      topByLikes.forEach((p, i) => {
        console.log(`   ${i + 1}. ${formatNum(p.likes)} likes | "${p.text.slice(0, 50)}..."`);
        console.log(`      ${p.url}`);
      });

      const topByRetweets = [...postsArray].sort((a, b) => b.retweets - a.retweets).slice(0, 5);
      console.log('\n🔄 TOP 5 BY RETWEETS:');
      topByRetweets.forEach((p, i) => {
        console.log(`   ${i + 1}. ${formatNum(p.retweets)} RTs | "${p.text.slice(0, 50)}..."`);
        console.log(`      ${p.url}`);
      });

      const topByRate = postsArray
        .filter(p => p.views > 0)
        .map(p => ({ ...p, rate: (p.engagement / p.views) * 100 }))
        .sort((a, b) => b.rate - a.rate)
        .slice(0, 5);
      if (topByRate.length > 0) {
        console.log('\n📈 TOP 5 BY ENGAGEMENT RATE:');
        topByRate.forEach((p, i) => {
          console.log(`   ${i + 1}. ${p.rate.toFixed(2)}% | "${p.text.slice(0, 50)}..."`);
          console.log(`      ${p.url}`);
        });
      }

      console.log('\n📉 LOWEST PERFORMING (consider deleting or learning from):');
      [...postsArray].sort((a, b) => a.likes - b.likes).slice(0, 3).forEach((p, i) => {
        console.log(`   ${i + 1}. ${p.likes} likes | "${p.text.slice(0, 50)}..."`);
        console.log(`      ${p.url}`);
      });
    }

    if (CONFIG.saveToLocalStorage) {
      const storageKey = `xactions_engagement_${username}`;
      const n = postsArray.length;
      localStorage.setItem(storageKey, JSON.stringify({
        username,
        timestamp: new Date().toISOString(),
        postCount: n,
        totals: { likes: totalLikes, retweets: totalRetweets, replies: totalReplies, views: totalViews },
        averages: { likes: totalLikes / n, retweets: totalRetweets / n, replies: totalReplies / n, views: totalViews / n },
        posts: postsArray,
      }));
      console.log('\n💾 Data saved! Run again to compare over time.');
      console.log(`📥 Export: copy(localStorage.getItem("${storageKey}"))`);
    }

    if (CONFIG.exportResults) {
      const report = {
        username,
        analyzedAt: new Date().toISOString(),
        summary: { totalLikes, totalRetweets, totalReplies, totalViews, avgEngRate, postsAnalyzed: postsArray.length },
        bestTimes: { bestHour: bestHour?.[0], bestDay: bestDay?.[0] },
        posts: postsArray,
      };
      const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `xactions-analytics-${username}-${new Date().toISOString().slice(0, 10)}.json`;
      a.click();
      console.log('\n📥 Full report downloaded as JSON');
    }
  };

  run();
})();

});
