  register("unlikeAllPosts", function(){
(() => {
  'use strict';

  const CONFIG = {
    maxUnlikes: 50,                   // Max posts to unlike (or list, in dry run) per run
    skipKeywords: [],                 // Keep likes containing these words
    onlyKeywords: [],                 // Only unlike if contains these words (empty = all)
    dryRun: true,                     // Preview without unliking. SET FALSE TO EXECUTE
    confirmBeforeStart: true,         // Live runs ask with confirm() before the first unlike
    minDelay: 1500,
    maxDelay: 2500,
    scrollDelay: 2000,
    maxEmptyScrolls: 6,
    maxConsecutiveErrors: 10,
    rateLimitCooldown: 60000,
    exportOnComplete: true,
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  const SEL = {
    unlikeBtn: ['[data-testid="unlike"]', 'button[data-testid="unlike"]'],
    tweet:     ['article[data-testid="tweet"]', 'article[role="article"]'],
    tweetText: ['[data-testid="tweetText"]', '[lang]'],
    toast:     ['[data-testid="toast"]', '[role="alert"]'],
  };

  const $ = (s, c = document) => { for (const x of (Array.isArray(s) ? s : [s])) { const e = c.querySelector(x); if (e) return e; } return null; };
  const $$ = (s, c = document) => { for (const x of (Array.isArray(s) ? s : [s])) { const e = c.querySelectorAll(x); if (e.length) return [...e]; } return []; };

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const gaussian = (a, b) => Math.floor(a + ((Math.random() + Math.random()) / 2) * (b - a));
  const isRateLimited = () => { const t = $(SEL.toast); return t && /rate limit|try again|too many|slow down/i.test(t.textContent); };

  let paused = false, aborted = false;
  let unliked = 0, scanned = 0, skipped = 0, errors = 0, consecutiveErrors = 0;
  const startTime = Date.now();
  const unlikedLog = [];
  const seenArticles = new WeakSet();   // posts already counted, so dry runs and skips are not re-counted

  const formatTime = (seconds) => {
    if (seconds < 60) return `${seconds}s`;
    return `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
  };

  window.XActions = {
    pause()  { paused = true;  console.log('⏸️ Paused.'); },
    resume() { paused = false; console.log('▶️ Resumed.'); },
    abort()  { aborted = true; console.log('🛑 Aborting...'); },
    status() {
      const elapsed = ((Date.now() - startTime) / 1000).toFixed(0);
      console.log(`📊 Unliked: ${unliked} | Scanned: ${scanned} | Skipped: ${skipped} | Errors: ${errors} | ${elapsed}s`);
    },
  };

  // Stop switch kept from scripts/twitter/unlike-all.js (also used by the command center Stop button)
  window.stopUnlike = () => {
    aborted = true;
    console.log('🛑 Stopping after the current unlike...');
  };

  const shouldContinue = async () => { while (paused && !aborted) await sleep(500); return !aborted; };

  const extractTweetInfo = (article) => {
    const textEl = $(SEL.tweetText, article);
    const text = textEl ? textEl.textContent.trim() : '';
    const authorLink = article.querySelector('a[href^="/"][role="link"]');
    const author = authorLink ? (authorLink.getAttribute('href') || '').replace('/', '') : 'unknown';
    return { text: text.slice(0, 200), author };
  };

  const run = async () => {
    const W = 60;
    console.log('╔' + '═'.repeat(W) + '╗');
    console.log('║  💔 UNLIKE ALL POSTS' + ' '.repeat(W - 22) + '║');
    console.log('║  by nichxbt — v2.0' + ' '.repeat(W - 21) + '║');
    console.log('╚' + '═'.repeat(W) + '╝');

    if (!window.location.href.includes('/likes')) {
      console.error('❌ Navigate to x.com/YOUR_USERNAME/likes first!');
      return;
    }

    console.log(CONFIG.dryRun ? '🔍 DRY RUN: preview only' : '⚠️ LIVE MODE: posts WILL be unliked!');
    console.log(`⚙️ Max: ${CONFIG.maxUnlikes} | Delay: ${CONFIG.minDelay}-${CONFIG.maxDelay}ms | Dry run: ${CONFIG.dryRun} | Filters: skip ${CONFIG.skipKeywords.length}, only ${CONFIG.onlyKeywords.length}`);

    if (!CONFIG.dryRun && CONFIG.confirmBeforeStart) {
      const confirmed = confirm(
        `💔 Unlike All Posts\n\n` +
        `This will unlike up to ${CONFIG.maxUnlikes} posts.\n\n` +
        `⚠️ This action cannot be easily undone!\n\n` +
        `Click OK to proceed or Cancel to abort.`
      );
      if (!confirmed) {
        console.log('🛑 Operation cancelled by user.');
        return;
      }
    }
    console.log('💡 To stop early: window.stopUnlike()');

    let emptyScrolls = 0;

    while (unliked < CONFIG.maxUnlikes && emptyScrolls < CONFIG.maxEmptyScrolls) {
      if (!(await shouldContinue())) break;

      if (isRateLimited()) {
        console.warn(`🚨 Rate limit! Cooling down ${CONFIG.rateLimitCooldown / 1000}s...`);
        await sleep(CONFIG.rateLimitCooldown);
        continue;
      }

      const buttons = $$(SEL.unlikeBtn).filter(b => {
        const art = b.closest('article') || b.closest('[data-testid="tweet"]');
        return !art || !seenArticles.has(art);
      });

      if (buttons.length === 0) {
        emptyScrolls++;
        window.scrollTo(0, document.body.scrollHeight);
        await sleep(gaussian(CONFIG.scrollDelay, CONFIG.scrollDelay + 800));
        continue;
      }

      emptyScrolls = 0;

      for (const btn of buttons) {
        if (!(await shouldContinue())) break;
        if (unliked >= CONFIG.maxUnlikes) break;

        const article = btn.closest('article') || btn.closest('[data-testid="tweet"]');
        if (article) seenArticles.add(article);
        const info = article ? extractTweetInfo(article) : { text: '', author: 'unknown' };
        scanned++;

        // Keyword filters
        const textLower = info.text.toLowerCase();
        if (CONFIG.skipKeywords.length > 0 && CONFIG.skipKeywords.some(kw => textLower.includes(kw.toLowerCase()))) {
          skipped++;
          continue;
        }
        if (CONFIG.onlyKeywords.length > 0 && !CONFIG.onlyKeywords.some(kw => textLower.includes(kw.toLowerCase()))) {
          skipped++;
          continue;
        }

        if (CONFIG.dryRun) {
          console.log(`   🔍 Would unlike: @${info.author} — "${info.text.slice(0, 80)}..."`);
          unlikedLog.push({ ...info, timestamp: new Date().toISOString(), dryRun: true });
          unliked++;
          continue;
        }

        try {
          btn.scrollIntoView({ behavior: 'smooth', block: 'center' });
          await sleep(300);
          btn.click();
          unliked++;
          consecutiveErrors = 0;
          unlikedLog.push({ ...info, timestamp: new Date().toISOString() });

          if (unliked % 10 === 0) {
            const rate = (unliked / ((Date.now() - startTime) / 60000)).toFixed(1);
            console.log(`💔 Unliked ${unliked} posts | ${rate}/min`);
          }

          await sleep(gaussian(CONFIG.minDelay, CONFIG.maxDelay));
        } catch (e) {
          errors++;
          consecutiveErrors++;
          if (consecutiveErrors >= CONFIG.maxConsecutiveErrors) {
            console.error(`❌ ${CONFIG.maxConsecutiveErrors} consecutive errors — aborting.`);
            break;
          }
        }
      }

      if (consecutiveErrors >= CONFIG.maxConsecutiveErrors) break;

      window.scrollTo(0, document.body.scrollHeight);
      await sleep(gaussian(CONFIG.scrollDelay, CONFIG.scrollDelay + 800));
    }

    if (aborted) console.log('🛑 Stopped by user.');

    // Summary
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(0);
    const avgTime = unliked > 0 && !CONFIG.dryRun ? (elapsed / unliked).toFixed(2) + 's' : '-';
    console.log('\n╔' + '═'.repeat(48) + '╗');
    console.log('║  📊 UNLIKE ALL — RESULTS' + ' '.repeat(23) + '║');
    console.log('╠' + '═'.repeat(48) + '╣');
    console.log(`║  Unliked:     ${String(unliked).padEnd(31)}║`);
    console.log(`║  Scanned:     ${String(scanned).padEnd(31)}║`);
    console.log(`║  Skipped:     ${String(skipped).padEnd(31)}║`);
    console.log(`║  Errors:      ${String(errors).padEnd(31)}║`);
    console.log(`║  Duration:    ${formatTime(Number(elapsed)).padEnd(31)}║`);
    console.log(`║  Avg/unlike:  ${avgTime.padEnd(31)}║`);
    console.log('╚' + '═'.repeat(48) + '╝');

    if (CONFIG.dryRun && unliked > 0) {
      console.log(`\n⚡ Set dryRun = false and re-run to actually unlike ${unliked} posts.`);
    }

    if (CONFIG.exportOnComplete && unlikedLog.length > 0) {
      const blob = new Blob([JSON.stringify({ summary: { unliked, scanned, skipped, errors, dryRun: CONFIG.dryRun }, posts: unlikedLog }, null, 2)], { type: 'application/json' });
      const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
      a.download = `xactions-unliked-${CONFIG.dryRun ? 'preview' : 'log'}-${new Date().toISOString().slice(0, 10)}.json`;
      document.body.appendChild(a); a.click(); a.remove();
      console.log('📥 Log exported.');
    }
  };

  run();
})();

});
  register("unlikeOld", function(){
(async function unlikeOldTweets() {
  'use strict';

  // ═══════════════════════════════════════════════════════════════════════════
  // 🎛️ CONFIGURATION - Customize these settings
  // ═══════════════════════════════════════════════════════════════════════════
  const CONFIG = {
    daysOld: 30,               // Only unlike tweets older than this many days
    maxUnlikes: 500,           // Maximum number of tweets to unlike (set to Infinity for all)
    minDelay: 1000,            // Minimum delay between unlikes (ms)
    maxDelay: 2500,            // Maximum delay between unlikes (ms)
    scrollDelay: 1500,         // Delay after scrolling to load more tweets (ms)
    maxScrollAttempts: 10,     // Max scroll attempts when no new old tweets found
    logProgress: true          // Log progress updates
  };
try{if(typeof window!=='undefined'&&window.__XA_LAUNCH_CFG){Object.assign(CONFIG,window.__XA_LAUNCH_CFG);}}catch(_xa){}


  // ═══════════════════════════════════════════════════════════════════════════
  // 🎯 SELECTORS
  // ═══════════════════════════════════════════════════════════════════════════
  const SELECTORS = {
    unlikeButton: '[data-testid="unlike"]',
    tweet: 'article[data-testid="tweet"]',
    tweetText: '[data-testid="tweetText"]',
    timestamp: 'time[datetime]'
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // 🛠️ HELPERS
  // ═══════════════════════════════════════════════════════════════════════════
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  
  const randomDelay = () => {
    return Math.floor(Math.random() * (CONFIG.maxDelay - CONFIG.minDelay + 1)) + CONFIG.minDelay;
  };

  const formatTime = (seconds) => {
    if (seconds < 60) return `${seconds}s`;
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}m ${secs}s`;
  };

  const scrollToBottom = () => {
    window.scrollTo({
      top: document.body.scrollHeight,
      behavior: 'smooth'
    });
  };

  const getTweetAge = (tweetElement) => {
    const timeElement = tweetElement.querySelector(SELECTORS.timestamp);
    if (!timeElement) return null;
    
    const tweetDate = new Date(timeElement.getAttribute('datetime'));
    const now = new Date();
    const diffMs = now - tweetDate;
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    
    return {
      days: diffDays,
      date: tweetDate,
      isOld: diffDays >= CONFIG.daysOld
    };
  };

  const findOldTweetsWithUnlike = () => {
    const tweets = document.querySelectorAll(SELECTORS.tweet);
    const oldTweets = [];
    
    tweets.forEach(tweet => {
      const unlikeButton = tweet.querySelector(SELECTORS.unlikeButton);
      if (!unlikeButton) return;
      
      const age = getTweetAge(tweet);
      if (age && age.isOld) {
        oldTweets.push({
          element: tweet,
          button: unlikeButton,
          age: age
        });
      }
    });
    
    return oldTweets;
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // 🚀 MAIN SCRIPT
  // ═══════════════════════════════════════════════════════════════════════════
  
  console.clear();
  console.log(`
╔══════════════════════════════════════════════════════════════╗
║  📅 UNLIKE OLD TWEETS - XActions                             ║
║  by nichxbt                                                  ║
╚══════════════════════════════════════════════════════════════╝
  `);

  // Verify we're on the likes page
  if (!window.location.href.includes('/likes')) {
    console.error('❌ Error: Please navigate to your likes page first!');
    console.log('📍 Go to: x.com/YOUR_USERNAME/likes');
    return;
  }

  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - CONFIG.daysOld);

  console.log('📋 Configuration:');
  console.log(`   • Unlike tweets older than: ${CONFIG.daysOld} days`);
  console.log(`   • Cutoff date: ${cutoffDate.toLocaleDateString()}`);
  console.log(`   • Max unlikes: ${CONFIG.maxUnlikes === Infinity ? 'Unlimited' : CONFIG.maxUnlikes}`);
  console.log(`   • Delay range: ${CONFIG.minDelay}ms - ${CONFIG.maxDelay}ms`);
  console.log('');

  console.log('🚀 Starting unlike process for old tweets...');
  console.log('💡 To stop early: window.stopUnlike()');
  console.log('');

  // Stats tracking
  const stats = {
    unliked: 0,
    skipped: 0,
    errors: 0,
    startTime: Date.now(),
    processedTweets: new Set()
  };

  let scrollAttempts = 0;
  let consecutiveNoOldTweets = 0;
  let stopped = false;
  window.stopUnlike = () => {
    stopped = true;
    console.log('🛑 Stopping after the current unlike...');
  };

  // Main loop
  while (stats.unliked < CONFIG.maxUnlikes && !stopped) {
    // Find old tweets with unlike buttons
    const oldTweets = findOldTweetsWithUnlike();
    
    // Filter out already processed tweets
    const newOldTweets = oldTweets.filter(t => {
      const tweetId = t.element.getAttribute('aria-labelledby') || 
                      t.element.textContent.substring(0, 50);
      return !stats.processedTweets.has(tweetId);
    });

    if (newOldTweets.length === 0) {
      consecutiveNoOldTweets++;

      // Scroll to load more tweets. The Likes feed is sorted by like-recency,
      // not tweet age, so a long run of not-yet-old tweets is expected and
      // must not be treated as "reached the end" - only a feed that has
      // truly stopped growing (no new tweet articles after scrolling) means
      // there's nothing left to find.
      const tweetCountBefore = document.querySelectorAll(SELECTORS.tweet).length;

      // Check if we've been scrolling with no results
      if (consecutiveNoOldTweets >= 3) {
        console.log(`📜 Scrolling to find older tweets... (attempt ${scrollAttempts + 1}/${CONFIG.maxScrollAttempts})`);
      }

      scrollToBottom();
      await sleep(CONFIG.scrollDelay);

      const tweetCountAfter = document.querySelectorAll(SELECTORS.tweet).length;
      if (tweetCountAfter > tweetCountBefore) {
        // Feed is still growing - real progress, even though none of the
        // newly-loaded tweets qualified as "old" yet.
        scrollAttempts = 0;
      } else {
        scrollAttempts++;
        if (scrollAttempts >= CONFIG.maxScrollAttempts) {
          console.log('📭 Reached the end of the Likes feed. No more old tweets found.');
          break;
        }
      }
      continue;
    }

    // Reset counters when we find old tweets
    scrollAttempts = 0;
    consecutiveNoOldTweets = 0;

    // Process the first old tweet
    const { element, button, age } = newOldTweets[0];
    const tweetId = element.getAttribute('aria-labelledby') || 
                    element.textContent.substring(0, 50);
    
    stats.processedTweets.add(tweetId);

    try {
      // Scroll tweet into view
      element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      await sleep(400);
      
      // Click the unlike button
      button.click();
      stats.unliked++;
      
      // Log progress with age info
      if (CONFIG.logProgress && stats.unliked % 5 === 0) {
        const elapsed = Math.floor((Date.now() - stats.startTime) / 1000);
        console.log(`📅 Progress: ${stats.unliked} unliked | ⏱️ ${formatTime(elapsed)} elapsed`);
      } else {
        console.log(`💔 Unliked tweet from ${age.days} days ago (${age.date.toLocaleDateString()})`);
      }
      
      // Random delay before next action
      await sleep(randomDelay());
      
    } catch (error) {
      stats.errors++;
      console.warn(`⚠️ Error unliking tweet: ${error.message}`);
      await sleep(1000);
    }

    // Check if we've hit the limit
    if (stats.unliked >= CONFIG.maxUnlikes) {
      console.log(`🎯 Reached maximum unlike limit (${CONFIG.maxUnlikes})`);
      break;
    }
  }

  delete window.stopUnlike;

  // ═══════════════════════════════════════════════════════════════════════════
  // 📊 COMPLETION SUMMARY
  // ═══════════════════════════════════════════════════════════════════════════
  const totalTime = Math.floor((Date.now() - stats.startTime) / 1000);
  const avgTime = stats.unliked > 0 ? (totalTime / stats.unliked).toFixed(2) : 0;

  console.log('');
  console.log(`
╔══════════════════════════════════════════════════════════════╗
║  ✅ UNLIKE OLD TWEETS COMPLETE                               ║
╠══════════════════════════════════════════════════════════════╣
║  📋 Criteria: Tweets older than ${String(CONFIG.daysOld + ' days').padEnd(25)}║
║  📊 Results:                                                 ║
║     📅 Old tweets unliked: ${String(stats.unliked).padEnd(33)}║
║     ❌ Errors: ${String(stats.errors).padEnd(45)}║
║     ⏱️  Total time: ${formatTime(totalTime).padEnd(40)}║
║     📈 Avg time/unlike: ${String(avgTime + 's').padEnd(36)}║
╚══════════════════════════════════════════════════════════════╝
  `);

  console.log('👋 Thanks for using XActions! Follow @nichxbt for updates.');
  
  return stats;
})();

});
